(function(){'use strict';
const shipping=ActivityViews.shipping,M=BuyOrderMath,$=id=>document.getElementById(id),catalog=PRICE_CATALOG,byId=new Map(catalog.map(r=>[r.id,r])),market=FeatureMarket.create(),clone=x=>JSON.parse(JSON.stringify(x)),fmt=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({item:'T4_FIBER',quality:1,quantity:10000,days:3,share:10,fee:2.5,step:1,ceiling:'',mode:'cheap',cities:M.cities.slice(0,5),manual:{},placed:{},used:false});
let state=defaults(),result,request=0,context='',loadedAt='';
const panel=document.createElement('section');panel.id='buy-order-planner';panel.className='panel buy-order-planner';panel.dataset.foldIgnore='';panel.innerHTML=`<div class="section-heading"><div><h2>Закупочные ордера по городам</h2><p>Распределите большой заказ, затем перенесите цену и количество в рынок игры.</p></div><button id="order-refresh" class="button" type="button">Обновить рынок предмета</button></div><div class="order-fields"><label class="field">Что закупаем<select id="order-item"></select></label><label class="field">Нужно купить, шт.<input id="order-quantity" type="number" min="1" max="100000000" step="1"></label><label class="field">Качество<select id="order-quality">${[1,2,3,4,5].map((q,i)=>'<option value="'+q+'">'+['Обычное','Хорошее','Выдающееся','Отличное','Шедевр'][i]+'</option>').join('')}</select></label><label class="field">Приоритет<select id="order-mode"><option value="cheap">Минимальная стоимость закупки</option><option value="balanced">Распределить по активности городов</option></select></label><label class="field">Срок для расчёта лимитов, дней<input id="order-days" type="number" min="0.01" max="365" step="0.5"></label><label class="field">Доля наблюдаемого оборота, %<input id="order-share" type="number" min="0.01" max="100" step="1"></label></div><details class="order-options" data-fold-ignore><summary>Цена и комиссия ордеров</summary><div class="order-fields"><label class="field">Выше лучшей покупки на, серебро<input id="order-step" type="number" min="0" step="1"></label><label class="field">Максимальная цена / шт.<input id="order-ceiling" type="number" min="1" step="1" placeholder="Без ограничения"></label><label class="field">Постановка ордера, % · оценка<input id="order-fee" type="number" min="0" max="100" step="0.1"></label></div><p class="hint">Уточните комиссию в игре. Перевозка, повторная постановка и изменение цены в бюджет не входят.</p></details><p class="hint order-explanation">Лимит города = средний объём за день × срок × доля оборота. История AODP содержит ордера продажи: это ориентир активности, а не скорость заполнения ваших покупок. Срок не гарантирован. Свои цены и лимиты из игры можно задать ниже.</p><p id="order-market-status" class="hint" role="status"></p><details id="order-city-settings" class="order-options" data-fold-ignore open><summary>Города закупки и ручные лимиты</summary><p class="hint">Снимите галочку, чтобы исключить город. Пустое поле использует рынок или расчётный лимит. Ручная цена задаётся без надбавки.</p><div id="order-cities" class="order-cities">${M.cities.map(city=>`<article class="order-city" data-order-city-card="${city}"><label class="refining-check"><input type="checkbox" data-order-city="${city}"> <b>${city}</b></label><p class="hint" data-order-market="${city}"></p><div class="order-city-fields">${[['price','Своя цена / шт.',1],['daily','Свой объём / день',0],['limit','Свой лимит, шт.',1]].map(([key,label,min])=>`<label class="field">${label}<input type="number" min="${min}" step="${key==='daily'?'0.01':'1'}" data-order-manual="${city}" data-order-property="${key}" aria-label="${label} ${city}"></label>`).join('')}</div><button type="button" class="button" data-order-reset="${city}">Сбросить ручные значения</button></article>`).join('')}</div></details><div id="order-summary" class="ledger-metrics"></div><p id="order-plan-status" class="hint" role="status"></p><div class="section-heading"><h3>Ордеры для переноса в игру</h3><button id="order-export" class="button" type="button">Скачать ордеры CSV</button></div><p class="hint">Скопируйте количество и цену, выставьте ордер в нужном городе и отметьте его. Отметка сохраняется для этого количества и цены; изменение плана требует повторной проверки.</p><div id="order-results" class="order-results"></div><div id="order-excluded" class="hint"></div><p id="order-action-status" class="hint" role="status" aria-live="polite"></p>`;
shipping.panel.append(panel);
const jump=document.createElement('button');jump.id='ship-buy-orders';jump.className='button';jump.type='button';jump.textContent='Закупочные ордера';$('ship-new-batch').parentElement.append(jump);
const key=city=>[shipping.state.server,state.item,state.quality,city].join('|'),identity=()=>[shipping.state.server,state.item,state.quality].join('|');
function quote(city){const bid=market.buyOrder(shipping.state.server,state.item,city,state.quality),ask=market.quote(shipping.state.server,state.item,city,state.quality),row=market.row(shipping.state.server,state.item,city,state.quality);return {bid:bid.price,ask:ask.manual?0:ask.price,daily:bid.daily,bidValid:bid.price>0,volumeValid:bid.daily>0,manual:bid.manual,bidDate:bid.manual?bid.timestamp:row?.buy_price_max_date,reason:bid.reason,source:bid.sourceLabel};}
function save(){if(shipping.active())window.Workspace?.capture();}
function cancel(){request++;market.cancel();}
function renderResults(){const manual=Object.fromEntries(M.cities.map(c=>[c,state.manual[key(c)]||{}]));result=M.plan({...state,manual},quote);$('order-summary').innerHTML=[['Распределено',fmt(result.assigned)+' / '+fmt(state.quantity)+' шт.'],['Стоимость закупки',fmt(result.cost)],['Постановка · оценка',fmt(result.setup)],['Бюджет с комиссией',fmt(result.total)]].map(([label,n])=>'<div><span>'+label+'</span><b>'+n+'</b></div>').join('');$('order-plan-status').textContent=result.error||'Всё количество распределено. Проверьте цены в игре перед постановкой.';$('order-plan-status').classList.toggle('negative',!result.valid);$('order-export').disabled=!result.rows.length;
 const focusCity=document.activeElement?.dataset.orderPlaced;
 $('order-results').innerHTML=result.rows.map(r=>`<article class="order-result" data-order-result="${r.city}"><div class="section-heading"><h3>${r.city}</h3><label class="refining-check"><input type="checkbox" data-order-placed="${r.city}" ${state.placed[key(r.city)]===r.signature?'checked':''}> Ордер выставлен</label></div><div class="order-values"><div><span>Количество</span><strong>${fmt(r.quantity)}</strong><button type="button" class="button" data-order-copy="quantity" data-order-for="${r.city}">Копировать количество</button></div><div><span>Цена / шт.</span><strong>${fmt(r.price)}</strong><button type="button" class="button" data-order-copy="price" data-order-for="${r.city}">Копировать цену</button></div></div><p>Закупка ${fmt(r.cost)} + постановка ≈ ${fmt(r.setup)} = <b>${fmt(r.total)} серебра</b></p><p class="hint">Лимит города: ${fmt(r.capacity)} шт. · ${r.manualPrice?'цена вручную':'цена по лучшей покупке + надбавка'} · ${r.manualLimit?'лимит вручную':r.manualDaily?'объём вручную':'объём из истории продаж'}</p></article>`).join('')||'<p class="empty">Пока нет ордеров. Выберите города и обновите рынок либо задайте свои цены и лимиты.</p>';
 if(focusCity)panel.querySelector('[data-order-placed="'+focusCity+'"]')?.focus({preventScroll:true});
 $('order-excluded').innerHTML=result.excluded.map(r=>'<p><b>'+r.city+':</b> '+esc(r.reason)+'</p>').join('');
 for(const city of M.cities){const q=quote(city),m=manual[city],chosen=result.rows.find(r=>r.city===city),hint=panel.querySelector('[data-order-market="'+city+'"]');hint.textContent='Лучшая покупка: '+(q.bid?fmt(q.bid):'нет данных')+' · продажа: '+(q.ask?fmt(q.ask):'нет данных')+' · оборот продаж / день: '+(q.daily?fmt(q.daily):'нет данных')+(q.bidDate?' · '+(q.source||new Date(q.bidDate).toLocaleString('ru-RU')):'')+(q.reason?' · '+q.reason:'');const price=panel.querySelector('[data-order-manual="'+city+'"][data-order-property="price"]'),limit=panel.querySelector('[data-order-manual="'+city+'"][data-order-property="limit"]');price.placeholder=q.bid?String(q.manual?q.bid:Math.ceil(q.bid+Number(state.step))):'Цена из игры';limit.placeholder=chosen?String(chosen.capacity):String(Math.floor((m.daily??q.daily)*Number(state.days)*Number(state.share)/100)||'Нет данных');}
}
function render(){if(!byId.has(state.item))state.item='T4_FIBER';const item=byId.get(state.item);if(!item.quality)state.quality=1;$('order-item').innerHTML='<option value="'+esc(item.id)+'">'+esc(item.name)+'</option>';for(const field of ['quality','quantity','days','share','fee','step','ceiling','mode'])$('order-'+field).value=state[field];$('order-quality').disabled=!item.quality;
 if(context!==identity()){cancel();context=identity();loadedAt='';$('order-action-status').textContent='';}
 $('order-market-status').textContent=loadedAt||'Нажмите «Обновить рынок предмета». Можно задать свои цены и лимиты.';
 for(const city of M.cities){panel.querySelector('[data-order-city="'+city+'"]').checked=state.cities.includes(city);for(const prop of ['price','daily','limit'])panel.querySelector('[data-order-manual="'+city+'"][data-order-property="'+prop+'"]').value=state.manual[key(city)]?.[prop]??'';}renderResults();}
async function refresh(force=true){if(!shipping.active()||!state.used)return;const seq=++request,id=identity(),ticket=window.Workspace?.ticket();$('order-market-status').textContent='Загружаем покупки, продажи и историю выбранного предмета…';try{const message=await market.load(shipping.state.server,[state.item],force);if(seq!==request||!shipping.active()||id!==identity()||ticket&&!Workspace.accept(ticket))return;loadedAt=message||'Рынок обновлён · '+new Date().toLocaleTimeString('ru-RU');$('order-market-status').textContent=loadedAt;renderResults();}catch(error){if(seq===request&&shipping.active()&&id===identity())$('order-market-status').textContent='Рынок недоступен. Можно ввести цены и лимиты вручную.';}}
function reveal(){state.used=true;window.QuickNavigation?.reveal(panel);panel.scrollIntoView({block:'start',behavior:'instant'});save();refresh(false);}
function open(item,quantity,quality=1,server=$('server').value){cancel();if(window.Workspace){const opened=Workspace.open(Workspace.registry.section('buy-orders'),{context:{server}});if(!opened||!shipping.active()||shipping.state.server!==server)return;}else if(!shipping.active())CraftApp.navigate('shipping');if(item&&byId.has(item)){state.item=item;state.quality=byId.get(item).quality?quality:1;state.quantity=quantity;}state.used=true;render();reveal();}
jump.onclick=()=>open();$('order-refresh').onclick=()=>{state.used=true;save();refresh(true);};
ItemPicker.attach('order-item',{getItems:()=>catalog,pick:r=>{cancel();state.item=r.id;if(!r.quality)state.quality=1;state.used=true;render();save();refresh(false);}});
panel.addEventListener('input',e=>{const el=e.target,prop=el.dataset.orderProperty,city=el.dataset.orderManual;if(city&&prop){const k=key(city);state.manual[k]||={};if(el.value==='')delete state.manual[k][prop];else state.manual[k][prop]=Number.isFinite(el.valueAsNumber)?el.valueAsNumber:null;renderResults();save();return;}const field=el.id.replace('order-','');if(['quantity','days','share','fee','step','ceiling'].includes(field)){state[field]=el.value;renderResults();save();}});
panel.addEventListener('change',e=>{const el=e.target;if(el.dataset.orderCity){state.cities=[...panel.querySelectorAll('[data-order-city]:checked')].map(n=>n.dataset.orderCity);renderResults();save();}else if(el.dataset.orderPlaced){const row=result.rows.find(r=>r.city===el.dataset.orderPlaced);if(row){if(el.checked)state.placed[key(row.city)]=row.signature;else delete state.placed[key(row.city)];save();}}else if(el.id==='order-mode'){state.mode=el.value;renderResults();save();}else if(el.id==='order-quality'){cancel();state.quality=Number(el.value);render();save();refresh(false);}});
async function copy(value){try{await navigator.clipboard.writeText(String(value));}catch{const input=document.createElement('textarea'),focus=document.activeElement;input.value=String(value);input.className='order-copy-buffer';document.body.append(input);input.select();const ok=document.execCommand('copy');input.remove();focus?.focus({preventScroll:true});if(!ok)throw Error('Не удалось скопировать. Выделите значение вручную.');}}
panel.addEventListener('click',async e=>{const reset=e.target.closest('[data-order-reset]');if(reset){delete state.manual[key(reset.dataset.orderReset)];render();save();return;}const button=e.target.closest('[data-order-copy]');if(!button)return;const row=result.rows.find(r=>r.city===button.dataset.orderFor);if(!row)return;try{await copy(row[button.dataset.orderCopy]);$('order-action-status').textContent=(button.dataset.orderCopy==='price'?'Цена':'Количество')+' для '+row.city+' скопировано.';}catch(error){$('order-action-status').textContent=error.message;}});
$('order-export').onclick=()=>{const rows=[['Сервер','Предмет','Качество','Город','Количество','Цена / шт.','Закупка','Комиссия (оценка)','Бюджет','Ордер выставлен'],...result.rows.map(r=>[shipping.state.server,byId.get(state.item).name,state.quality,r.city,r.quantity,r.price,r.cost,r.setup,r.total,state.placed[key(r.city)]===r.signature?'Да':'Нет'])],csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='buy-orders-'+state.item+'-'+shipping.state.server+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const capture=shipping.captureDraft,restore=shipping.restoreDraft,draw=shipping.render,deactivate=shipping.deactivate,load=shipping.refresh;
shipping.captureDraft=()=>({...capture(),buyOrders:clone(state)});
shipping.restoreDraft=d=>{cancel();state={...defaults(),...clone(d?.buyOrders||{})};restore(d);render();};
shipping.render=()=>{draw();render();};shipping.deactivate=()=>{cancel();deactivate();};shipping.refresh=force=>Promise.all([load(force),refresh(force)]);
document.addEventListener('workspacechange',e=>{if(!e.detail?.navigation||!shipping.active())return;const snapshot=Workspace.snapshot(),tab=snapshot.tabs.find(t=>t.id===snapshot.active);if(tab?.target.id==='buy-orders'){const ticket=Workspace.ticket();requestAnimationFrame(()=>{if(shipping.active()&&Workspace.accept(ticket))reveal();});}});
function procurementButtons(){for(const row of document.querySelectorAll('#materials [data-material-details]')){const id=row.dataset.materialDetails;if(!id||row.querySelector('[data-order-material]'))continue;const button=document.createElement('button');button.type='button';button.className='button';button.dataset.orderMaterial=id;button.textContent='Ордеры на покупку';row.append(button);}}
document.addEventListener('craftresultchange',procurementButtons);$('materials').addEventListener('click',e=>{const button=e.target.closest('[data-order-material]');if(!button)return;const x=CraftApp.snapshot(),m=x.result.bill.find(m=>m.id===button.dataset.orderMaterial);if(m)open(m.id,m.buy,m.preserveQuality?Number(x.config.quality):1,x.server);});
window.BuyOrderUI={open,refresh,snapshot:()=>({state:clone(state),plan:clone(result)}),market};render();procurementButtons();
})();
